const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
let state,undoStack=[],stream=null,recognition=null,source='typed',pinning=null,tracker=null,tracking=null,trackingTimer=null,trackingBusy=false,referenceLoaded=null,activePhoto=null,toastTimer,renderToken=0;
try{state=readState()||exampleState();}catch(e){state=emptyState();setTimeout(()=>toast('Saved data could not be read. Restore a backup in Settings.'),300);}
const task=()=>state.tasks.find(t=>t.id===state.activeId)||null;
const relative=d=>{const m=Math.max(0,Math.floor((Date.now()-Date.parse(d))/60000));return m<1?'just now':m<60?`${m} min ago`:m<1440?`${Math.floor(m/60)} hr ago`:`${Math.floor(m/1440)} days ago`;};
const date=d=>new Date(d).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function toast(message,undo=false){clearTimeout(toastTimer);const box=$('#toast');box.innerHTML=esc(message)+(undo?' <button id="toast-undo">Undo</button>':'');box.hidden=false;if(undo)$('#toast-undo').onclick=undoLast;toastTimer=setTimeout(()=>box.hidden=true,6500);}
function commit(next,message){try{writeState(next);undoStack.push(clone(state));undoStack=undoStack.slice(-15);state=next;render();if(message)toast(message,true);return true;}catch(e){toast('Could not save. Your previous data is safe. Export a backup and check device storage.');return false;}}
