function fitPlane(){const el=stream?$('#camera'):$('#scene'),w=el.videoWidth||el.naturalWidth||1200,h=el.videoHeight||el.naturalHeight||760;const view=$('#viewport'),plane=$('#media-plane');const scale=Math.min(view.clientWidth/w,view.clientHeight/h);Object.assign(plane.style,{width:`${w*scale}px`,height:`${h*scale}px`,left:`${(view.clientWidth-w*scale)/2}px`,top:`${(view.clientHeight-h*scale)/2}px`,right:'auto',bottom:'auto'});}
new ResizeObserver(fitPlane).observe($('#viewport'));$('#scene').onload=fitPlane;$('#camera').onloadedmetadata=fitPlane;
function renderMarkers(){const t=task(),overlay=$('#overlay');overlay.replaceChildren();if(!t||stream&&!tracking?.ok)return;if(!t.example&&!t.reference&&!activePhoto&&!stream)return;
  const ns='http://www.w3.org/2000/svg';
  t.steps.forEach((step,index)=>{if(!step.marker)return;const p=stream?project(tracking.matrix,step.marker):step.marker;if(!p||p.x<0||p.x>1||p.y<0||p.y>1)return;
    const x=p.x*1200,y=p.y*760,active=step.status==='active',done=step.status==='done',color=active?'#f0c586':done?'#d4efbe':'#c3d5ba';
    const g=document.createElementNS(ns,'g');g.setAttribute('class','marker');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',`${step.title}: ${step.status}`);
    const label=step.title.length>24?step.title.slice(0,23)+'…':step.title,labelWidth=Math.max(115,label.length*9+40),labelX=Math.max(12,Math.min(1200-labelWidth-12,x+28));
    g.innerHTML=`<circle cx="${x}" cy="${y}" r="${active?26:20}" fill="${color}" fill-opacity=".1" stroke="${color}" stroke-opacity=".35"/><circle cx="${x}" cy="${y}" r="${active?12:8}" fill="${color}" stroke="#22331c" stroke-width="2"/><path d="M${x+20} ${y}L${labelX} ${y-39}" stroke="${color}" stroke-opacity=".7" fill="none"/><rect x="${labelX}" y="${y-66}" width="${labelWidth}" height="37" rx="8" fill="#152319" fill-opacity=".9" stroke="${color}" stroke-opacity=".5"/><text x="${labelX+13}" y="${y-42}" fill="${color}" font-family="system-ui,sans-serif" font-size="15" font-weight="500">${done?'✓ ':active?'↝ ':''}${esc(label)}</text>`;
    g.onclick=()=>editStep(step.id);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();editStep(step.id);}};overlay.append(g);
  });
}

function newTask(){dialog('Start a new thread',`<p class="dialog-copy">Give your project a name and a few steps. You can capture the little details as you go.</p><form id="new-form"><label class="field"><span>Workspace name</span><input id="new-title" required maxlength="100" placeholder="e.g. Repot my desk plant" autocomplete="off"></label><label class="field"><span>Steps · one per line</span><textarea id="new-steps" required rows="5" placeholder="Prepare the pot\nMove the plant\nAdd soil and water" maxlength="5000"></textarea><small>A short checklist is enough. Your checkpoints capture the rest.</small></label><div class="form-row"><button type="button" class="button" id="fill-example">Use organizer steps</button><button type="submit" class="button primary">Create workspace ${icon('arrow')}</button></div><p id="form-error" class="form-error" role="alert"></p></form>`,'A PLACE FOR YOUR NEXT PROJECT');$('#fill-example').onclick=()=>{$('#new-title').value='Build a desk organizer';$('#new-steps').value='Assemble the base\nAttach the dividers\nFit the back panel\nFinish & tidy';};$('#new-form').onsubmit=handle(e=>{e.preventDefault();if(state.tasks.length>=MAX_TASKS)throw new Error('You have 30 workspaces. Export a backup and remove an old one in Settings.');const t=makeTask($('#new-title').value,$('#new-steps').value.split('\n'));const next=clone(state);next.tasks.push(t);next.activeId=t.id;if(commit(next,'Workspace created. Open your camera or add a photo.')){stopCamera();activePhoto=null;referenceLoaded=null;closeDialog();render();}});}
function renameTask(){const t=task();if(!t)return newTask();dialog('Make it yours',`<form id="rename-form"><label class="field"><span>Workspace name</span><input id="rename-title" required maxlength="100" value="${esc(t.title)}"></label><label class="field"><span>Add another step · optional</span><input id="append-step" maxlength="160" placeholder="e.g. Sand the edges"></label><div class="form-row"><button class="button primary" type="submit">Save changes</button></div></form>`);$('#rename-form').onsubmit=handle(e=>{e.preventDefault();const title=$('#rename-title').value.trim(),extra=$('#append-step').value.trim();if(!title)return;if(update(t=>{t.title=title;if(extra){if(t.steps.length>=MAX_STEPS)throw new Error('A workspace supports up to 30 steps.');t.steps.push({id:uid(),title:extra,status:currentStep(t)?'todo':'active',detail:'',next:'',marker:null});if(t.status==='complete')t.status='active';}recordEvent(t,'edit',{label:'Updated workspace'});},'Workspace updated.'))closeDialog();});}
function editStep(id){const t=task(),s=t?.steps.find(s=>s.id===id);if(!s)return;dialog(s.title,`<form id="step-form"><label class="field"><span>Step name</span><input id="step-title" value="${esc(s.title)}" required maxlength="160"></label><label class="field"><span>Progress</span><select id="step-status"><option value="todo" ${s.status==='todo'?'selected':''}>Not started</option><option value="active" ${s.status==='active'?'selected':''}>In progress</option><option value="done" ${s.status==='done'?'selected':''}>Done · clear unfinished detail</option></select></label><label class="field"><span>What’s unfinished?</span><textarea id="step-detail" maxlength="1000" rows="2">${esc(s.detail)}</textarea></label><label class="field"><span>Exact next action</span><input id="step-next" value="${esc(s.next)}" maxlength="1000"></label><div class="step-edit-actions"><button type="submit" class="button primary">Save step</button><button type="button" class="button" id="step-pin">${icon('pin')}Place marker</button>${s.marker?'<button type="button" class="button" id="remove-marker">Remove marker</button>':''}</div></form>`,'STEP '+String(t.steps.indexOf(s)+1).padStart(2,'0'));$('#step-form').onsubmit=handle(e=>{e.preventDefault();const title=$('#step-title').value.trim(),status=$('#step-status').value,detail=$('#step-detail').value.trim(),next=$('#step-next').value.trim();if(update(t=>{const step=t.steps.find(x=>x.id===id);step.title=title;setStepStatus(t,id,status);if(status!=='done'){step.detail=detail;step.next=next;}},'Step updated.'))closeDialog();});$('#step-pin').onclick=()=>{closeDialog();startPin(id);};if($('#remove-marker'))$('#remove-marker').onclick=()=>{update(t=>t.steps.find(s=>s.id===id).marker=null,'Marker removed.');closeDialog();};}

async function checkpoint(pauseAfter=false){const t=task();if(!t)return newTask();const s=currentStep(t);source='typed';dialog(pauseAfter?'Save your place':'Leave a checkpoint',`<p class="dialog-copy">Capture the detail your future self will need. Everything below is yours to review.</p><div class="note-actions"><button class="button" id="record-note">${icon('mic')}Speak a note</button><button class="button" id="suggest-note">${icon('note')}Extract details</button></div><form id="checkpoint-form"><label class="field"><span>Your note</span><textarea id="note-text" rows="3" maxlength="2000" required placeholder="The dividers are positioned, but I haven’t glued them. Next: glue the left divider."></textarea></label><label class="field"><span>Step this belongs to</span><select id="note-step">${t.steps.map(x=>`<option value="${esc(x.id)}" ${x.id===s?.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label class="field"><span>Unfinished detail · optional</span><textarea id="note-unfinished" rows="2" maxlength="1000" placeholder="Positioned, but not glued"></textarea></label><label class="field"><span>Next action · optional</span><input id="note-next" maxlength="1000" placeholder="Glue the left divider"></label><label class="check-field"><input type="checkbox" id="note-complete"><span>This step is fully complete. Clear its unfinished detail.</span></label><label class="check-field"><input type="checkbox" id="note-photo" ${stream||activePhoto?'checked':''} ${stream||activePhoto?'':'disabled'}><span>Attach a photo from ${stream?'the camera':'this workspace'}${!stream&&!activePhoto?' · open the camera or a photo first':''}</span></label><div class="review-box" style="margin-top:16px"><p>Progress changes only when you save. “Extract details” uses simple text cues; review the result. It does not inspect the photo.</p></div><div class="form-row"><button type="submit" class="button primary">${icon('check')}${pauseAfter?'Save checkpoint & pause':'Save checkpoint'}</button></div><p class="form-error" id="checkpoint-error" role="alert"></p></form>`,'YOUR WORK, REMEMBERED');
  $('#record-note').onclick=handle(recordVoice);$('#suggest-note').onclick=()=>{const p=suggestCheckpoint($('#note-text').value);$('#note-unfinished').value=p.unfinished;$('#note-next').value=p.next;$('#note-complete').checked=p.complete;toast('Details extracted. Review before saving.');};
  $('#checkpoint-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const input={stepId:$('#note-step').value,note:$('#note-text').value,unfinished:$('#note-unfinished').value,next:$('#note-next').value,complete:$('#note-complete').checked,source};if(input.complete&&input.unfinished.trim()){throw new Error('This note has an unfinished detail. Uncheck completion or clear the detail first.');}const photo=$('#note-photo').checked?await capturePhoto():null;if(photo){input.imageId=uid();await putImage(input.imageId,photo);}const ok=update(t=>{saveCheckpoint(t,input);if(pauseAfter&&t.status!=='complete'){t.status='paused';recordEvent(t,'pause',{label:'Paused with a checkpoint'});}},pauseAfter?'Your place is saved. See you when you’re ready.':'Checkpoint saved. Your future self is covered.');if(ok){closeDialog();if(pauseAfter)stopCamera();}}catch(error){$('#checkpoint-error').textContent=error.message;}finally{submit.disabled=false;}};
}
function stopVoice(){if(recognition){recognition.onend=null;recognition.stop();recognition=null;}}
function recordVoice(){if(recognition){stopVoice();const b=$('#record-note');if(b){b.classList.remove('recording');b.innerHTML=icon('mic')+'Speak a note';}return;}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)throw new Error('Speech recognition is unavailable in this browser. Type your note, or try Safari on your iPhone.');recognition=new Speech();recognition.lang='en-US';recognition.continuous=false;recognition.interimResults=false;const b=$('#record-note');b.classList.add('recording');b.innerHTML=icon('mic')+'Listening… tap to stop';recognition.onresult=e=>{const text=[...e.results].map(r=>r[0].transcript).join(' '),field=$('#note-text');if(field){field.value=(field.value+' '+text).trim().slice(0,2000);source='voice';const p=suggestCheckpoint(field.value);$('#note-unfinished').value=p.unfinished;$('#note-next').value=p.next;$('#note-complete').checked=p.complete;}};recognition.onerror=e=>toast(e.error==='not-allowed'?'Microphone or speech access was denied. You can type the checkpoint.':`Speech could not finish (${e.error}). You can type instead.`);recognition.onend=()=>{recognition=null;if(b.isConnected){b.classList.remove('recording');b.innerHTML=icon('mic')+'Speak a note';}};try{recognition.start();}catch(e){stopVoice();throw e;}}
function speak(){const t=task();if(!t)return;if(!('speechSynthesis'in window))return toast('Read-aloud is unavailable in this browser.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(resumePacket(t).summary);u.rate=.96;speechSynthesis.speak(u);}
async function resume(){const t=task();if(!t)return newTask();if(t.status==='active')return checkpoint(true);const p=resumePacket(t);let image=p.checkpoint?.imageId?await getImage(p.checkpoint.imageId).catch(()=>null):null;dialog(t.status==='complete'?'Look how far you came':'Here’s your thread',`${image?`<img class="resume-evidence" src="${image}" alt="Photo evidence saved with your checkpoint">`:''}<div class="resume-packet"><div class="packet-row"><small>LAST COMPLETED</small><strong>${esc(p.lastCompleted)}</strong></div><div class="packet-row"><small>LEFT UNFINISHED</small><strong>${esc(p.unfinished||'No unresolved detail recorded.')}</strong></div><div class="packet-row next"><small>YOUR NEXT MOVE</small><strong>${esc(p.nextAction)}</strong></div></div><p class="help-text">${p.checkpoint?`From your confirmed ${p.checkpoint.source} checkpoint · ${esc(date(p.checkpoint.at))}`:'Based on the steps you marked complete.'}</p><div class="form-row"><button class="button" id="resume-read">${icon('volume')}Read aloud</button><button class="button primary" id="resume-confirm">${t.status==='complete'?'Back to workspace':'Pick up the thread'} ${icon('arrow')}</button></div>`,'WELCOME BACK');$('#resume-read').onclick=speak;$('#resume-confirm').onclick=()=>{if(t.status!=='complete')update(t=>{t.status='active';recordEvent(t,'resume',{label:'Resumed from saved checkpoint'});});closeDialog();scan();toast('Your next move is highlighted. Open the camera to return to the real workspace.');};}
function scan(){const sweep=$('#scan-sweep');sweep.hidden=false;sweep.style.animation='none';void sweep.offsetWidth;sweep.style.animation='';setTimeout(()=>sweep.hidden=true,1800);}
async function history(){const t=task();if(!t)return newTask();dialog('Your saved thread',t.checkpoints.length?`<div id="timeline">${[...t.checkpoints].reverse().map(c=>`<article class="timeline-item"><time>${esc(date(c.at))} · ${c.source==='voice'?'Voice':'Typed'} checkpoint</time><p>${esc(c.note)}</p>${c.unfinished?`<small>Unfinished: ${esc(c.unfinished)}</small>`:''}${c.next?`<small>Next: ${esc(c.next)}</small>`:''}${c.done?'<small>Step confirmed complete</small>':''}${c.imageId?`<img data-evidence="${esc(c.imageId)}" alt="Saved checkpoint photo" hidden>`:''}</article>`).join('')}</div>`:'<p class="dialog-copy">Your first checkpoint starts the story. Capture what’s done, what’s unfinished, and what comes next.</p>','CHECKPOINT HISTORY');for(const el of $$('[data-evidence]')){const image=await getImage(el.dataset.evidence).catch(()=>null);if(image&&el.isConnected){el.src=image;el.hidden=false;}}}

async function startCamera(){if(!task())return newTask();if(stream){stopCamera();return;}if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access requires HTTPS and a supported browser. You can add a photo instead.');const b=$('#camera-button');b.disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});$('#camera').srcObject=stream;$('#camera').hidden=false;$('#scene').hidden=true;await $('#camera').play();$('#view-tag').innerHTML='<span></span> LIVE CAMERA';$('#view-tag').classList.add('live');b.innerHTML=icon('camera')+'<span>Stop camera</span>';tracking=null;referenceLoaded=null;$('#tracking-status').textContent=task().reference?'Finding saved workspace…':'Tap Align to set a workspace reference';$('#tracking-status').classList.add('warn');renderMarkers();fitPlane();await loadReference();trackingTimer=setInterval(trackFrame,850);toast('Camera is live. Photos stay on this device.');}catch(e){stopCamera();throw new Error(e.name==='NotAllowedError'?'Camera access was denied. Allow it in your browser or add a workspace photo.':e.name==='NotFoundError'?'No camera was found. Add a workspace photo instead.':'The camera could not start. Close other camera apps and try again.');}finally{b.disabled=false;}}
function stopCamera(){if(trackingTimer)clearInterval(trackingTimer);trackingTimer=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#camera').srcObject=null;$('#camera').hidden=true;$('#ghost').hidden=true;$('#ghost-button').setAttribute('aria-pressed','false');tracking=null;render();}
function frameCanvas(el,max=960){const w=el.videoWidth||el.naturalWidth,h=el.videoHeight||el.naturalHeight;if(!w||!h)throw new Error('Wait for the camera or photo to finish loading.');const scale=Math.min(1,max/Math.max(w,h)),c=document.createElement('canvas');c.width=Math.round(w*scale);c.height=Math.round(h*scale);c.getContext('2d',{willReadFrequently:true}).drawImage(el,0,0,c.width,c.height);return c;}
async function capturePhoto(){if(stream)return frameCanvas($('#camera')).toDataURL('image/jpeg',.82);if(activePhoto)return activePhoto;return null;}
async function imageFrame(data){const img=new Image();img.src=data;await img.decode();const c=frameCanvas(img,480);return c.getContext('2d').getImageData(0,0,c.width,c.height);}
async function loadReference(){const t=task();if(!stream||!t?.reference)return;const id=t.reference;try{const data=await getImage(id);if(!data||task()?.reference!==id)return;tracker ||= new PlanarTracker();const count=tracker.setReference(await imageFrame(data));referenceLoaded=id;if(count<12)$('#tracking-status').textContent='Reference needs texture. Try a patterned mat or printed page.';}catch(e){$('#tracking-status').textContent='Tracking unavailable. Photo checkpoints still work.';}}
async function trackFrame(){if(trackingBusy||!stream||!tracker?.reference||referenceLoaded!==task()?.reference)return;trackingBusy=true;try{const c=frameCanvas($('#camera'),480),r=tracker.match(c.getContext('2d').getImageData(0,0,c.width,c.height));tracking=r;$('#tracking-status').textContent=r.ok?`Planar match · ${r.inliers} inliers · surface markers`:`${r.reason} · markers hidden`;$('#tracking-status').classList.toggle('warn',!r.ok);renderMarkers();}catch{tracking=null;renderMarkers();$('#tracking-status').textContent='Alignment lost · point back at your reference';$('#tracking-status').classList.add('warn');}finally{trackingBusy=false;}}
async function align(){const t=task();if(!t)return newTask();if(!stream&&!activePhoto&&!t.example)return toast('Open your camera or add a workspace photo first.');dialog('Give your work a reference',`<p class="dialog-copy">Keep your phone steady and include a textured, flat surface, such as a cutting mat or printed page. Threadback matches visible features to keep markers aligned with that plane.</p><div class="review-box warn"><h3>What this tracks</h3><p>Markers refer to places on the workspace plane. Moving an object does not move its marker. If alignment is uncertain, markers are hidden.</p></div><p class="help-text">Setting a new reference clears old marker positions so you can place them accurately again. Your steps, notes, and checkpoints stay saved.</p><div class="form-row"><button class="button primary" id="set-reference">${icon('scan')}Use this view</button></div>`,'HONEST SPATIAL MEMORY');$('#set-reference').onclick=handle(async e=>{e.currentTarget.disabled=true;const data=await capturePhoto();if(!data){closeDialog();toast('The example already has an illustrative reference. Start your own workspace for live tracking.');return;}const id=uid();await putImage(id,data);const ok=update(t=>{t.reference=id;t.example=false;t.steps.forEach(s=>s.marker=null);recordEvent(t,'reference',{label:'Set a new workspace reference'});},'Reference saved. Place a marker on your current step.');if(ok){referenceLoaded=null;await loadReference();if(stream)await trackFrame();closeDialog();startPin(currentStep(task())?.id);}});}
function startPin(id){const t=task();if(!t)return newTask();if(!id)return toast('Choose an unfinished step first.');if(stream&&!tracking?.ok)return toast('Align the workspace first. Markers stay hidden until tracking is reliable.');if(!stream&&!t.example&&!t.reference&&!activePhoto)return toast('Add a workspace photo or open your camera first.');pinning=id;$('#media-plane').classList.add('pinning');$('#scene-hint').innerHTML=icon('pin')+'<span>Tap the workspace to place this step. Escape cancels.</span>';$('#scene-hint').style.display='flex';toast('Tap a place on the workspace for this step.');}
$('#media-plane').addEventListener('click',e=>{if(!pinning||e.target.closest('.marker'))return;const r=$('#media-plane').getBoundingClientRect();let p={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};if(stream){const inv=tracking?.ok?inverse(tracking.matrix):null;if(!inv)return toast('Alignment was lost. Try again after tracking recovers.');p=project(inv,p);}if(!p||p.x<0||p.x>1||p.y<0||p.y>1)return toast('Choose a point inside the reference workspace.');const id=pinning;update(t=>{const s=t.steps.find(s=>s.id===id);if(s)s.marker=p;recordEvent(t,'marker',{label:'Placed a step marker'});},'Marker placed.');cancelPin();});
function cancelPin(){pinning=null;$('#media-plane').classList.remove('pinning');$('#scene-hint').innerHTML=icon('pin')+'<span>Progress has a place.</span>';$('#scene-hint').style.display='';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')cancelPin();});
async function loadPhoto(file){if(!file)return;if(!task())return newTask();if(file.size>20*1024*1024)throw new Error('Choose a photo smaller than 20 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPEG, PNG, or WebP photo.');const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();activePhoto=frameCanvas(img).toDataURL('image/jpeg',.82);}finally{URL.revokeObjectURL(url);}stopCamera();const id=uid();await putImage(id,activePhoto);update(t=>{t.reference=id;t.example=false;t.steps.forEach(s=>s.marker=null);recordEvent(t,'photo',{label:'Opened a new workspace photo'});},'Photo saved as your workspace reference. Place markers where you need them.');referenceLoaded=null;tracking=null;render();}
async function toggleGhost(){const g=$('#ghost');if(!g.hidden){g.hidden=true;$('#ghost-button').setAttribute('aria-pressed','false');return;}const t=task(),c=t?.checkpoints.findLast(c=>c.imageId);if(!c)return toast('Save a checkpoint with a photo to compare it here.');const image=await getImage(c.imageId);if(!image)return toast('That checkpoint photo is missing. Your note is still saved.');if(stream&&!tracking?.ok)return toast('Align with the saved workspace before comparing photos.');if(stream)return toast('Pause the camera to compare saved photos. Live perspective warping is not supported yet.');g.src=image;g.hidden=false;$('#ghost-button').setAttribute('aria-pressed','true');toast('Translucent checkpoint photo. Different viewpoints may not line up.');}

function guide(){dialog('A little memory. A lot more flow.',`<p class="dialog-copy">Threadback is a visual bookmark for physical projects. It saves the details that make returning easier.</p><div class="guide-steps"><div class="guide-step"><div><strong>Give your project a thread</strong><p>Create a workspace with a few steps. Open the camera or add a photo.</p></div></div><div class="guide-step"><div><strong>Leave the useful detail</strong><p>Speak or type what changed, what’s still unfinished, and your exact next move. Review and save the checkpoint.</p></div></div><div class="guide-step"><div><strong>Put progress in its place</strong><p>Set a reference and place step markers. Live tracking works on textured, mostly flat surfaces. When uncertain, it hides markers.</p></div></div><div class="guide-step"><div><strong>Return without retracing</strong><p>Pause, close the app, and come back. Your resume packet separates completed work, unfinished details, and the next action.</p></div></div></div><div class="review-box" style="margin-top:20px"><p>Camera observation runs only while the app is visible and the camera is on. Completion is confirmed by you. The illustrated example is not live recognition.</p></div><div class="form-row"><button class="button primary" id="guide-done">Got it ${icon('check')}</button></div>`,'PICK UP YOUR THREAD');$('#guide-done').onclick=closeDialog;}
function settings(){dialog('Your workspace, your data',`<p class="dialog-copy">Tasks and photos are saved in this browser on this device. Export a backup before clearing browser data or switching devices.</p><div class="review-box"><h3>Private by design</h3><p>Threadback does not upload camera frames, photos, or notes. Browser speech recognition may use your browser provider’s speech service. The camera stops when you leave the app.</p></div><div class="settings-section"><h3>Take your thread with you</h3><button class="button" id="export-data">Export backup ${icon('arrow')}</button><button class="button" id="import-data">Import backup</button><p class="help-text">JSON backup includes your notes and photo evidence. Keep it somewhere private.</p></div><div class="settings-section"><h3>Workspace controls</h3><button class="button" id="undo-setting" ${undoStack.length?'':'disabled'}>Undo last change</button><button class="button" id="load-example">Open the example</button><button class="button danger" id="delete-task">Remove this workspace</button></div><div class="settings-section"><h3>About this build</h3><p class="help-text">Threadback · v0.1 · Arbiter Hacks V1<br>Local planar tracking; voice availability depends on your browser. Text extraction uses simple rules, not a cloud AI model.</p><a class="text-button" href="https://github.com/ShivaPriyanShanmuga/threadback-mobile" target="_blank" rel="noopener">Source, roadmap & known limits ↗</a></div>`,'LOCAL-FIRST, ALWAYS');$('#export-data').onclick=handle(async()=>{const data=await backup(state),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`threadback-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported. It includes your photos and notes.');});$('#import-data').onclick=()=>$('#backup-input').click();$('#undo-setting').onclick=()=>{undoLast();closeDialog();};$('#load-example').onclick=()=>{const ex=exampleState().tasks[0],next=clone(state);if(next.tasks.length>=MAX_TASKS)return toast('Remove a workspace before adding another.');next.tasks.push(ex);next.activeId=ex.id;stopCamera();activePhoto=null;referenceLoaded=null;commit(next,'Illustrated example opened.');closeDialog();};$('#delete-task').onclick=()=>{const t=task();if(!t)return;dialog('Remove this workspace?',`<p class="dialog-copy">Remove <strong>${esc(t.title)}</strong> from your workspace list? You can undo this during this session. Export a backup first to preserve it beyond this session.</p><div class="form-row"><button class="button" id="delete-cancel">Keep workspace</button><button class="button danger" id="delete-confirm">Remove workspace</button></div>`);$('#delete-cancel').onclick=settings;$('#delete-confirm').onclick=()=>{stopCamera();activePhoto=null;const next=clone(state);next.tasks=next.tasks.filter(x=>x.id!==t.id);next.activeId=next.tasks[0]?.id||null;commit(next,'Workspace removed.');closeDialog();};};}
$('#backup-input').onchange=handle(async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>32*1024*1024)throw new Error('Choose a backup smaller than 32 MB.');const data=JSON.parse(await f.text());dialog('Restore this backup?',`<p class="dialog-copy">This replaces the workspace list on this device. Export your current backup first if you want to keep it.</p><div class="form-row"><button class="button" id="import-cancel">Cancel</button><button class="button primary" id="import-confirm">Restore backup</button></div>`);$('#import-cancel').onclick=settings;$('#import-confirm').onclick=handle(async()=>{const previous=clone(state),next=await restore(data);undoStack.push(previous);state=next;stopCamera();activePhoto=null;referenceLoaded=null;closeDialog();render();toast('Backup restored.',true);});});

$('#new-top').onclick=newTask;$('#new-side').onclick=newTask;$('#start-own').onclick=newTask;$('#edit-task').onclick=renameTask;$('#checkpoint-button').onclick=()=>checkpoint();$('#resume-button').onclick=handle(resume);$('#speak-button').onclick=speak;$('#history-nav').onclick=handle(history);$('#all-history').onclick=handle(history);$('#last-checkpoint').onclick=handle(history);$('#guide-nav').onclick=guide;$('#tour-button').onclick=guide;$('#settings-nav').onclick=settings;$('#privacy-button').onclick=settings;$('#workspace-nav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('#camera-button').onclick=handle(startCamera);$('#align-button').onclick=handle(align);$('#pin-button').onclick=()=>startPin(currentStep(task())?.id);$('#upload-photo').onclick=()=>$('#photo-input').click();$('#photo-input').onchange=handle(async e=>{const f=e.target.files[0];e.target.value='';await loadPhoto(f);});$('#ghost-button').onclick=handle(toggleGhost);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVoice();if(stream)stopCamera();if('speechSynthesis'in window)speechSynthesis.cancel();}});
window.addEventListener('pagehide',()=>{if(stream)stream.getTracks().forEach(t=>t.stop());});
window.addEventListener('storage',e=>{if(e.key==='threadback.workspace.v1'){try{state=readState()||emptyState();undoStack=[];activePhoto=null;referenceLoaded=null;stopCamera();render();toast('Workspace updated from another tab.');}catch{toast('Another tab saved unreadable data. Your current view is unchanged.');}}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
render();

